def is_power_of_five(N):
    if N <= 0:
        return None
    k = 0
    temp_N = N
    while temp_N > 1:
        if temp_N % 5 != 0:
            return None
        temp_N //= 5
        k += 1
    return k

solutions = []
for n in range(3, 31):
    N = (2**n) - 3
    k = is_power_of_five(N)
    if k is not None:
        solutions.append((n, k))

print("Solutions found (n, k):")
for n, k in solutions:
    print(f"({n}, {k})")
